INSERT INTO public.categories (id, name, slug, description, cover_image_url) VALUES
('a0000001-0000-0000-0000-000000000001', 'Nature', 'nature', 'Breathtaking landscapes, misty forests, alpine summits, and serene coastlines.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80'),
('a0000001-0000-0000-0000-000000000002', 'Architecture', 'architecture', 'Bold geometries, minimalist pavilions, brutalist concrete, and classical colonnades.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80'),
('a0000001-0000-0000-0000-000000000003', 'Wildlife', 'wildlife', 'Untamed creatures in their natural habitats, from arctic foxes to savannah monarchs.', 'https://images.unsplash.com/photo-1546182990-dffeafbe841d?auto=format&fit=crop&w=800&q=80'),
('a0000001-0000-0000-0000-000000000004', 'Travel', 'travel', 'Transcendent journeys through historic canals, ancient temples, and distant horizons.', 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w=800&q=80'),
('a0000001-0000-0000-0000-000000000005', 'Street', 'street', 'Unrehearsed human moments, neon reflections, rainy avenues, and candid urban poetry.', 'https://images.unsplash.com/photo-1508873696983-2df5293cb325?auto=format&fit=crop&w=800&q=80')
INSERT INTO public.images (id, title, description, image_url, category_id, tags, photographer, location, camera, is_featured, aspect_ratio) VALUES
('b0000001-0000-0000-0000-000000000001', 'Ethereal Mist in the Dolomites', 'Morning clouds drift through the dramatic jagged peaks of the Italian Alps.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1600&q=85', 'a0000001-0000-0000-0000-000000000001', ARRAY['mountains', 'fog', 'italy', 'alps'], 'Luca Moretti', 'Val di Funes, Italy', 'Sony A7R V • 24-70mm f/2.8 GM', true, 'landscape'),
('b0000001-0000-0000-0000-000000000002', 'Solitude of Mount Rainier', 'A towering volcanic peak crowned with ancient glaciers stands resilient against twilight hues.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1600&q=85', 'a0000001-0000-0000-0000-000000000001', ARRAY['mountain', 'snow', 'glacier'], 'Elena Rostova', 'Washington, USA', 'Canon EOS R5 • 70-200mm f/2.8L', false, 'portrait'),
('b0000001-0000-0000-0000-000000000003', 'Whispers of the Forest Canopy', 'Dense fog weaves through emerald redwood treetops as the first rays of morning light pierce the quiet forest.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1600&q=85', 'a0000001-0000-0000-0000-000000000001', ARRAY['forest', 'mist', 'morning'], 'David K. Vance', 'Black Forest, Germany', 'Nikon Z8 • 50mm f/1.8 S', true, 'landscape'),
('b0000001-0000-0000-0000-000000000004', 'Geometric Ascent of Glass & Steel', 'Reflective structural glass facades form rhythmic diagonal patterns.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1600&q=85', 'a0000001-0000-0000-0000-000000000002', ARRAY['skyscraper', 'geometry', 'glass'], 'Sophie Laurent', 'Frankfurt, Germany', 'Hasselblad X2D 100C • 45mm f/4', true, 'portrait'),
('b0000001-0000-0000-0000-000000000005', 'Monarch of the Savannah', 'A powerful African lion rests attentively on a sunlit knoll.', 'https://images.unsplash.com/photo-1546182990-dffeafbe841d?auto=format&fit=crop&w=1600&q=85', 'a0000001-0000-0000-0000-000000000003', ARRAY['lion', 'savannah', 'wildlife'], 'Samuel Ochieng', 'Serengeti, Tanzania', 'Nikon Z9 • 400mm f/2.8 TC VR', true, 'landscape'),
('b0000001-0000-0000-0000-000000000006', 'Dawn Gondolas of the Grand Canal', 'Traditional handcrafted wooden gondolas bob peacefully at their moorings.', 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w=1600&q=85', 'a0000001-0000-0000-0000-000000000004', ARRAY['venice', 'gondola', 'italy'], 'Matteo Rossi', 'Venice, Italy', 'Leica M11 • 35mm f/2 Summicron', true, 'landscape'),
('b0000001-0000-0000-0000-000000000007', 'Rain, Reflections, and Yellow Cabs', 'A sudden afternoon rainstorm transforms Manhattan tarmac into a glossy liquid mirror.', 'https://images.unsplash.com/photo-1508873696983-2df5293cb325?auto=format&fit=crop&w=1600&q=85', 'a0000001-0000-0000-0000-000000000005', ARRAY['nyc', 'rain', 'taxi'], 'Miles Thornton', 'New York City, USA', 'Leica Q2 Monochrom • 28mm f/1.7', true, 'portrait')
